SELECT


WHERE v.deleted = 0

    AND v.vin LIKE CONCAT('%', #{query.vin}, '%')


    AND p.model_id = #{query.modelId}


    AND i.date_to_storage_yard >= #{query.storageStartDate}


    AND i.date_to_storage_yard <= #{query.storageEndDate}



        AND v.lifecycle_stage = 'PENDING_INBOUND'


        AND i.stage_status = #{query.stageStatus}


        AND 1 = 0


ORDER BY v.id DESC
